# Lanternhold v141 Ember Ring (John, 27 Nov 2026: keep PvP and PvE separate). Paste into AWS CloudShell (us-east-1). Needs John's go.
# Code-only update of lanternhold-arena: dungeon power no longer counts in any fight (the game used to send it and could
# fake it); each class starts from its own Ring health and attack instead (sim: class win rates 42-59%, were 36-66%).
# Stops if the live code is not the v140 code it expects. Backs up the function to ~/lhbak and prints the undo command.
set -e
F=lanternhold-arena; T=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhv141r && cd ~/lhv141r
curl -s -o live.zip "$(aws lambda get-function --function-name $F --query Code.Location --output text)"
[ "$(unzip -p live.zip index.js | md5sum | cut -c1-32)" = "f4e484a4187f6b1a16d1cd01b466653b" ] || { echo "lanternhold-arena is not the v140 code this script expects. Stopping; nothing changed. Ask Claude."; exit 1; }
cp live.zip ~/lhbak/$F-$T.zip; echo "backup: ~/lhbak/$F-$T.zip"
echo  | base64 -d > index.js
[ "$(md5sum index.js | cut -c1-32)" = "b5be1a8f2708991da80d6ecf038daa43" ] || { echo "The code did not paste cleanly. Nothing changed."; exit 1; }
rm -f ring.zip && zip -qj ring.zip index.js
aws lambda update-function-code --function-name $F --zip-file fileb://ring.zip >/dev/null
aws lambda wait function-updated --function-name $F
echo "done. Undo: aws lambda update-function-code --function-name $F --zip-file fileb://$HOME/lhbak/$F-$T.zip"
